#!/usr/bin/env python3
"""Build / refresh the standalone ARM replay probe package under ``ml_training/arm_probe``.

The package is deliberately small and self-contained:
* frozen artefacts copied into ``model/`` with SHA-256 pinned in the manifest;
* selected real/synthetic IQ frames copied into ``frames/`` (no path outside the package is
  needed at replay time);
* package-local NumPy runtime in ``runtime/`` (copy of the frozen inference path);
* ``input_manifest.json`` (frame list, truth/context, hashes);
* host expected outputs in ``expected/`` (generated by the package's own runtime);
* host clean-directory replay and cross-checks in ``host/``;
* ``MANIFEST.json`` file hashes, counts and build metadata.

This script is a **build-time** tool; it is not needed on the board.  It writes only under
``ml_training/arm_probe`` and the temporary clean-directory copy (removed afterwards).
"""
from __future__ import annotations

import ast
import hashlib
import json
import os
import shutil
import subprocess
import sys
import tempfile
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
ML = ROOT / "ml_training"
PKG = ML / "arm_probe"
EVIDENCE = ROOT / "evidence" / "rf-teaching"
CAMPAIGN5 = EVIDENCE / "codex-s2-takeover-2026-10-18" / "campaign5-val-followup" / "download"
CAMPAIGN3 = EVIDENCE / "s2" / "46db-trainval-campaign3-2026-10-18" / "download" / "train-01"
NEW_RAW = EVIDENCE / "s2-46db-80mhz-narrowband-2026-10-21" / "raw"
SIM = ML / "round2" / "datasets" / "sim-r2"

if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))
if str(PKG) not in sys.path:
    sys.path.insert(0, str(PKG))

from ml_training.common.dataset import load_manifest, load_split  # noqa: E402
from ml_training.model.numpy_runtime import load_model as project_load_model  # noqa: E402
from ml_training.round2.predictor import Round2Predictor as ProjectPredictor  # noqa: E402
from ml_training.common.preprocess import preprocess_iq as project_preprocess  # noqa: E402

import run_replay  # noqa: E402

CLASSES = ("BPSK", "QPSK", "QAM16", "QAM64")
FROZEN = {
    "cnn_model": (ML / "artifacts" / "cnn" / "model.json",
                  "25a65fb1e6a7bb606d7611c473d166b8b633256b3a72dcadd434ed83a38c49cc"),
    "baseline_model": (ML / "artifacts" / "baseline" / "model.json",
                       "caa8258916268892bad968e1240520da0c03ab825839fc2f39c5bb534c4e3014"),
    "rule_config": (ML / "round2" / "artifacts" / "rule_config.json",
                    "9aceebbdb6b9b9a54ad0dd09ebd61935ae8c8fd276ba18d8b9db69e7949619e0"),
}
BANNED_IMPORTS = ("torch", "scipy", "sklearn", "pandas", "ml_training")


def sha256_bytes(data):
    return hashlib.sha256(data).hexdigest()


def sha256_file(path):
    return sha256_bytes(Path(path).read_bytes())


def utc_now():
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def rel(path):
    return str(Path(path).resolve().relative_to(ROOT)).replace("\\", "/")


def verify_frozen():
    records = {}
    for name, (path, expected) in FROZEN.items():
        if not path.is_file():
            raise SystemExit("missing frozen artifact: %s" % path)
        actual = sha256_file(path)
        if actual != expected:
            raise SystemExit("frozen artifact changed: %s (%s != %s)"
                             % (path, actual, expected))
        records[name] = {"path": rel(path), "sha256": actual,
                         "bytes": path.stat().st_size}
    return records


def copy_models():
    model_dir = PKG / "model"
    model_dir.mkdir(parents=True, exist_ok=True)
    targets = {"cnn_model": "cnn_model.json", "baseline_model": "baseline_model.json",
               "rule_config": "rule_config.json"}
    for name, filename in targets.items():
        source = FROZEN[name][0]
        target = model_dir / filename
        target.write_bytes(source.read_bytes())
        if sha256_file(target) != FROZEN[name][1]:
            raise SystemExit("model copy hash mismatch: %s" % target)


def _real_entry(identifier, group, kind, truth, source_path, source_text):
    return {"id": identifier, "group": group, "kind": kind, "truth": truth,
            "source": source_text, "source_path": Path(source_path)}


def collect_real_entries():
    entries = []

    def add_campaign5(session, frames, group):
        for index in frames:
            entries.append(_real_entry(
                "%s-%s-normal-%02d" % (group.replace("_", "-"), session, index),
                group, "clean",
                {"class": "BPSK", "modulation_truth": "submitted TX config BPSK/3M/RECT",
                 "note": "physical loopback normal frame"},
                CAMPAIGN5 / session / ("normal-%02d.iq" % index),
                rel(CAMPAIGN5 / session / ("normal-%02d.iq" % index))))

    for session in ("train-01", "val-01"):
        add_campaign5(session, (1, 2, 3), "clean_real_bpsk")
    for index in (1, 2, 3):
        entries.append(_real_entry(
            "clean-real-campaign3-normal-%02d" % index, "clean_real_bpsk", "clean",
            {"class": "BPSK", "modulation_truth": "independent session TX config BPSK/3M/RECT",
             "note": "independent physical session"},
            CAMPAIGN3 / ("normal-%02d.iq" % index),
            rel(CAMPAIGN3 / ("normal-%02d.iq" % index))))
    for index in range(1, 11):
        entries.append(_real_entry(
            "clean-fail-train02-normal-%02d" % index, "clean_failure_bpsk", "clean",
            {"class": "BPSK", "modulation_truth": "submitted TX config BPSK/3M/RECT",
             "note": "previous round-1 CNN failure session (QPSK misclassification)"},
            CAMPAIGN5 / "train-02" / ("normal-%02d.iq" % index),
            rel(CAMPAIGN5 / "train-02" / ("normal-%02d.iq" % index))))
    entries.append(_real_entry(
        "clean-real-new-normal", "clean_real_bpsk", "clean",
        {"class": "BPSK", "modulation_truth": "submitted TX config BPSK/3M/RECT; demod BER=0",
         "note": "new 2026-10-21 normal frame"},
        NEW_RAW / "nf-00-normal.iq", rel(NEW_RAW / "nf-00-normal.iq")))
    for session in ("train-01", "train-02", "val-01"):
        entries.append(_real_entry(
            "gate-off-%s" % session, "gate_off", "gate",
            {"expected_behavior": "reject", "gate_kind": "OFF",
             "note": "physical OFF/background frame (no TX)"},
            CAMPAIGN5 / session / "off-01.iq", rel(CAMPAIGN5 / session / "off-01.iq")))
    for index in (1, 2, 3):
        entries.append(_real_entry(
            "stress-narrowband-%02d" % index, "stress_narrowband", "stress",
            {"class_underlying": "BPSK",
             "note": "BPSK + injected 6 MHz tone; demod not synced; not clean data"},
            NEW_RAW / ("nf-%02d-narrowband.iq" % index),
            rel(NEW_RAW / ("nf-%02d-narrowband.iq" % index))))
    return entries


def collect_synthetic_entries():
    manifest = load_manifest(SIM)
    entries = []
    test = load_split(SIM, manifest, "test", labels=list(CLASSES))
    counters = {label: 0 for label in CLASSES}
    for index in range(len(test["X"])):
        label = str(test["label"][index])
        snr = float(test["snr_db"][index])
        if counters[label] >= 2 or abs(snr - 20.0) > 1e-6:
            continue
        counters[label] += 1
        iq = test["X"][index]
        identifier = "clean-syn-%s-snr20-%02d" % (label.lower(), counters[label])
        entries.append({"id": identifier, "group": "clean_synthetic_4class", "kind": "clean",
                        "truth": {"class": label,
                                  "modulation_truth": "synthetic round-2 test, SNR 20 dB"},
                        "source": "ml_training/round2/datasets/sim-r2 test split (SNR 20 dB)",
                        "iq": iq})
    gate = load_split(SIM, manifest, "gate_test", kinds=["TONE", "NOISE", "CLIP"],
                      include_clipped=True)
    per_kind = {"TONE": 0, "NOISE": 0, "CLIP": 0}
    for index in range(len(gate["X"])):
        kind = str(gate["label"][index])
        if per_kind.get(kind, 0) >= 3:
            continue
        per_kind[kind] += 1
        identifier = "gate-%s-%02d" % (kind.lower(), per_kind[kind])
        entries.append({"id": identifier, "group": "gate_%s" % kind.lower(), "kind": "gate",
                        "truth": {"expected_behavior": "reject", "gate_kind": kind,
                                  "note": "synthetic gate_test %s frame" % kind},
                        "source": "ml_training/round2/datasets/sim-r2 gate_test (%s)" % kind,
                        "iq": gate["X"][index]})
    missing = [label for label, count in counters.items() if count < 2]
    if missing:
        raise SystemExit("not enough synthetic test frames for classes: %r" % missing)
    return entries


def materialise_frames(entries):
    frames_dir = PKG / "frames"
    if frames_dir.exists():
        shutil.rmtree(frames_dir)
    manifest_entries = []
    for entry in entries:
        group_dir = frames_dir / entry["group"]
        group_dir.mkdir(parents=True, exist_ok=True)
        target = group_dir / (entry["id"] + ".iq")
        if "source_path" in entry:
            raw = Path(entry["source_path"]).read_bytes()
        else:
            iq = entry["iq"]
            if iq.shape != (4096, 2):
                raise SystemExit("synthetic frame shape invalid: %r" % (iq.shape,))
            raw = iq.astype("<i2").tobytes()
        target.write_bytes(raw)
        manifest_entries.append({
            "id": entry["id"], "group": entry["group"], "kind": entry["kind"],
            "truth": entry["truth"], "source": entry["source"],
            "path": "frames/%s/%s.iq" % (entry["group"], entry["id"]),
            "iq_sha256": sha256_bytes(raw), "bytes": len(raw),
        })
    manifest_entries.sort(key=lambda item: item["id"])
    return manifest_entries


def write_input_manifest(frozen_records, frames):
    document = {
        "schema": "ml-modrec-arm-probe-input-v1",
        "created_utc": utc_now(),
        "purpose": "frozen round-2 offline pipeline replay for independent ARM qualification",
        "frozen": frozen_records,
        "frames": frames,
        "groups": {},
        "data_use_note": (
            "clean groups are used for label/rejection replay only; stress/gate groups are "
            "reported separately and never counted in clean 4-class accuracy"),
        "no_device_note": "package only; no board connection, deployment or product change",
    }
    for frame in frames:
        group = document["groups"].setdefault(frame["group"], {"n": 0, "ids": []})
        group["n"] += 1
        group["ids"].append(frame["id"])
    (PKG / "input_manifest.json").write_text(json.dumps(document, indent=1),
                                             encoding="utf-8")
    return document


def write_expected(predictor, manifest):
    result = run_replay.evaluate(predictor, manifest)
    expected_dir = PKG / "expected"
    expected_dir.mkdir(parents=True, exist_ok=True)
    (expected_dir / "host_expected.json").write_text(json.dumps(result, indent=1),
                                                     encoding="utf-8")
    summary = result["summary"]
    lines = ["# Host expected replay summary (frozen package)", "",
             "Package: `ml_training/arm_probe`; frames: %d." % len(result["frames"]), "",
             "Clean classification (host expected; BPSK real + synthetic 4-class):", "",
             "| group | n | truth classes | before correct | after correct | before acc | after acc |",
             "|---|---|---|---|---|---|---|"]
    for name in sorted(summary["clean"]):
        item = summary["clean"][name]
        if name == "__total__":
            continue
        lines.append("| %s | %d | %s | %d | %d | %.4f | %.4f |" % (
            name, item["n"], ",".join(item["truth_classes"]), item["before_correct"],
            item["after_correct"], item["before_accuracy"], item["after_accuracy"]))
    total = summary["clean"]["__total__"]
    lines += ["", "**Clean total**: n=%d, before %d/%d (%.4f), after %d/%d (%.4f); %s" % (
        total["n"], total["before_correct"], total["n"], total["before_accuracy"],
        total["after_correct"], total["n"], total["after_accuracy"], total["note"]), "",
        "Gate populations (rejection expected; not clean labels):", "",
        "| group | n | rejected | accepted | reasons |", "|---|---|---|---|---|"]
    for name in sorted(summary["gate"]):
        item = summary["gate"][name]
        lines.append("| %s | %d | %d | %d | %s |" % (
            name, item["n"], item["rejected"], item["accepted"],
            json.dumps(item["reasons"], sort_keys=True)))
    lines += ["", "Interference stress (separate from clean accuracy):", ""]
    for name in sorted(summary["stress"]):
        item = summary["stress"][name]
        lines.append("- **%s**: n=%d; after labels %s; reasons %s; %s" % (
            name, item["n"], item["after_labels"], item["after_reasons"], item["note"]))
    lines += ["", "Expected values are the frozen host outputs from the package's own runtime;",
              "the ARM replay must match labels/reasons/arbitration exactly and stay within the",
              "documented numeric tolerances (see COMPATIBILITY.md)."]
    (expected_dir / "host_summary.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    return result


def project_cross_check(manifest, predictor):
    project_cnn = project_load_model(FROZEN["cnn_model"][0])
    project_predictor = ProjectPredictor()
    mismatches = []
    max_logit_delta = 0.0
    for entry in manifest["frames"]:
        iq = run_replay.read_frame(PKG / entry["path"])
        package_before = run_replay._before_decision(predictor.cnn, iq)
        project_before = project_cnn.predict_iq(iq)
        package_after = predictor.decide(iq)
        project_after = project_predictor.decide(iq)
        for section, package_decision, project_decision in (
                ("before", package_before, project_before),
                ("after", package_after, project_after)):
            if package_decision["label"] != project_decision["label"]:
                mismatches.append({"id": entry["id"], "section": section,
                                   "package": package_decision["label"],
                                   "project": project_decision["label"]})
            if (package_decision.get("reason") or "") != (project_decision.get("reason") or ""):
                mismatches.append({"id": entry["id"], "section": section,
                                   "package_reason": package_decision.get("reason"),
                                   "project_reason": project_decision.get("reason")})
        x, gate = project_preprocess(iq)
        if gate.get("ok"):
            package_logits = predictor.cnn.forward(x)
            project_logits = project_cnn.forward(x)
            max_logit_delta = max(max_logit_delta,
                                  float(max(abs(a - b) for a, b in
                                            zip(package_logits, project_logits))))
    result = {"frames": len(manifest["frames"]), "mismatches": mismatches,
              "mismatch_count": len(mismatches),
              "max_abs_logit_delta": max_logit_delta,
              "note": "package runtime vs project frozen runtime (same host NumPy)",
              "status": "PASS" if not mismatches else "FAIL"}
    (PKG / "host" / "project_cross_check.json").write_text(json.dumps(result, indent=1),
                                                           encoding="utf-8")
    return result


def compatibility_check():
    files = sorted(list((PKG / "runtime").glob("*.py")) + [PKG / "run_replay.py"])
    arm_script = PKG / "arm" / "run_arm_probe.py"
    if arm_script.is_file():
        files.append(arm_script)
    syntax_ok = True
    imports = {}
    errors = []
    for path in files:
        source = path.read_text(encoding="utf-8")
        try:
            tree = ast.parse(source, filename=str(path), feature_version=(3, 8))
        except SyntaxError as exc:
            syntax_ok = False
            errors.append({"path": rel(path), "error": str(exc)})
            continue
        modules = set()
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                modules.update(alias.name.split(".")[0] for alias in node.names)
            elif isinstance(node, ast.ImportFrom) and node.level == 0 and node.module:
                modules.add(node.module.split(".")[0])
        imports[rel(path)] = sorted(modules)
    banned = sorted({module for values in imports.values() for module in values
                     if module in BANNED_IMPORTS})
    result = {
        "target": {"python": "3.8.x", "numpy": "1.17.4", "machine": "ARMv7l"},
        "host": {"python": sys.version.split()[0], "numpy": __import__("numpy").__version__},
        "python_syntax_3_8_ok": syntax_ok,
        "syntax_errors": errors,
        "imports": imports,
        "banned_imports_found": banned,
        "pure_numpy_only": not banned,
        "note": ("static syntax/import check only; runtime numeric equality on ARM must be "
                 "verified by the bounded replay/timing probe"),
    }
    (PKG / "host" / "compatibility_check.json").write_text(json.dumps(result, indent=1),
                                                           encoding="utf-8")
    return result


def clean_directory_run(manifest, expected):
    temp = Path(tempfile.mkdtemp(prefix="ml-arm-probe-clean-"))
    try:
        copy = temp / "arm_probe"
        shutil.copytree(PKG, copy, ignore=shutil.ignore_patterns("__pycache__", "host"))
        env = dict(os.environ)
        env.pop("PYTHONPATH", None)
        completed = subprocess.run(
            [sys.executable, "-I", "run_replay.py", "--check", "--out", "results.json"],
            cwd=str(copy), env=env, capture_output=True, text=True)
        log = {"command": "python -I run_replay.py --check --out results.json",
               "cwd": "clean temporary copy (removed)",
               "returncode": completed.returncode,
               "stdout": completed.stdout, "stderr": completed.stderr,
               "check_passed": completed.returncode == 0}
        results_path = copy / "results.json"
        problems = ["result JSON missing"] if not results_path.is_file() else []
        if results_path.is_file():
            actual = json.loads(results_path.read_text(encoding="utf-8"))
            problems.extend(run_replay.compare(expected, actual))
        log["comparison_problems"] = problems[:20]
        log["problem_count"] = len(problems)
        log["status"] = "PASS" if completed.returncode == 0 and not problems else "FAIL"
        (PKG / "host").mkdir(parents=True, exist_ok=True)
        (PKG / "host" / "host_clean_run.log").write_text(
            json.dumps(log, indent=1) + "\n--- stdout ---\n" + completed.stdout
            + "\n--- stderr ---\n" + completed.stderr, encoding="utf-8")
        (PKG / "host" / "host_clean_run.json").write_text(
            json.dumps({key: log[key] for key in
                        ("command", "returncode", "check_passed", "problem_count",
                         "comparison_problems", "status")}, indent=1), encoding="utf-8")
        return log
    finally:
        shutil.rmtree(temp, ignore_errors=True)


def write_manifest(frozen_records, frames, expected, cross, compat, clean_run):
    files = []
    for path in sorted(PKG.rglob("*")):
        if not path.is_file() or "__pycache__" in path.parts:
            continue
        if path.name == "MANIFEST.json":
            continue
        files.append({"path": rel(path), "bytes": path.stat().st_size,
                      "sha256": sha256_file(path)})
    counts = {}
    for frame in frames:
        counts[frame["group"]] = counts.get(frame["group"], 0) + 1
    document = {
        "schema": "ml-modrec-arm-probe-manifest-v1",
        "created_utc": utc_now(),
        "package": "ml_training/arm_probe",
        "purpose": "standalone frozen round-2 pipeline replay for independent ARM qualification",
        "frozen": frozen_records,
        "frames": {"total": len(frames), "by_group": counts},
        "host_expected_sha256": sha256_file(PKG / "expected" / "host_expected.json"),
        "host_checks": {
            "project_cross_check": {key: cross[key] for key in
                                    ("status", "mismatch_count", "max_abs_logit_delta")},
            "compatibility_check": {key: compat[key] for key in
                                    ("python_syntax_3_8_ok", "pure_numpy_only",
                                     "banned_imports_found")},
            "clean_directory_run": {key: clean_run[key] for key in
                                    ("status", "returncode", "check_passed", "problem_count")},
        },
        "files": files,
        "files_total": len(files),
        "bytes_total": sum(item["bytes"] for item in files),
        "no_device_note": "software package only; no board connection, deployment or product change",
    }
    (PKG / "MANIFEST.json").write_text(json.dumps(document, indent=1), encoding="utf-8")


def main():
    frozen_records = verify_frozen()
    copy_models()
    entries = collect_real_entries() + collect_synthetic_entries()
    frames = materialise_frames(entries)
    manifest = write_input_manifest(frozen_records, frames)
    predictor = run_replay.load_predictor()
    expected = write_expected(predictor, manifest)
    cross = project_cross_check(manifest, predictor)
    compat = compatibility_check()
    clean_run = clean_directory_run(manifest, expected)
    write_manifest(frozen_records, frames, expected, cross, compat, clean_run)
    print(json.dumps({
        "frames": len(frames),
        "groups": manifest["groups"],
        "clean_total": expected["summary"]["clean"]["__total__"],
        "gate": {name: {"n": item["n"], "rejected": item["rejected"],
                        "reasons": item["reasons"]}
                 for name, item in expected["summary"]["gate"].items()},
        "stress": {name: {"n": item["n"], "after": item["after_labels"]}
                   for name, item in expected["summary"]["stress"].items()},
        "project_cross_check": cross["status"],
        "compatibility": {"syntax_3_8": compat["python_syntax_3_8_ok"],
                          "pure_numpy": compat["pure_numpy_only"],
                          "banned": compat["banned_imports_found"]},
        "clean_dir_run": clean_run["status"],
    }, indent=1))
    if cross["mismatch_count"] or not compat["python_syntax_3_8_ok"] \
            or not compat["pure_numpy_only"] or clean_run["status"] != "PASS":
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
